import json, glob, re, math, unicodedata
SELF="SESSION-20261127-c93065"; CAP="20261127"
def d8(i):
    m=re.search(r"-(\d{8})-", i or ""); return m.group(1) if m else "00000000"
def load(pat, base=None):
    rows=[]
    for f in sorted(glob.glob(pat)):
        for line in open(f,encoding="utf-8"):
            line=line.strip()
            if line:
                try: rows.append(json.loads(line))
                except Exception: pass
    if base and glob.glob(base):
        for line in open(base,encoding="utf-8"):
            line=line.strip()
            if line:
                try: rows.append(json.loads(line))
                except Exception: pass
    return rows
def norm(s): return re.sub(r"\s+","",unicodedata.normalize("NFKC", s or ""))
def zt(t1,n1,t2,n2):
    p=(t1+t2)/(n1+n2); se=math.sqrt(p*(1-p)*(1/n1+1/n2))
    if se==0: return (float("nan"),float("nan"))
    z=(t1/n1-t2/n2)/se
    return round(z,4), round(2*(1-0.5*(1+math.erf(abs(z)/math.sqrt(2)))),6)
mats=load("state/materials.d/*.jsonl","state/materials.jsonl")
notes=load("state/notes.d/*.jsonl","state/notes.jsonl")
reads=load("state/read_log.d/*.jsonl","state/read_log.jsonl")
sessions=load("state/sessions.d/*.jsonl","state/sessions.jsonl")
claim_texts=[]
for n in notes:
    if n.get("session_id")==SELF: continue
    for c in (n.get("claims") or []):
        if c.get("text"): claim_texts.append(c["text"])
parts=[]
for p in ("BELIEF_MAP.md","READING_MAP.md","docs/CONSOLIDATED_DIGESTS.md"):
    parts.append(open(p,encoding="utf-8").read())
parts.extend(claim_texts)
gist=norm("".join(parts))
by_mat={}
for r in reads:
    if r.get("session_id")==SELF: continue
    t=r.get("target") or {}
    if t.get("type")!="material": continue
    note=(r.get("note") or "")
    if "機械的バックフィル" in note or "backfill" in note.lower(): continue
    by_mat.setdefault(t.get("id"),[]).append(d8(r.get("read_id") or ""))
def reached(mid):
    md=d8(mid)
    return any(rd>md for rd in by_mat.get(mid,()))
pkt=set()
for s in sessions:
    sd=(s.get("started_at") or "")[:10].replace("-","")
    if sd and sd<=CAP: pkt.update(s.get("context_material_ids") or [])
stamp=[m for m in mats if "00000000"<d8(m["material_id"])<=CAP]
def era(m):
    d=d8(m["material_id"])
    return "pre" if d<="20261112" else ("reg" if d<="20261120" else "act")
P={m["material_id"] for m in stamp if len(norm(m.get("title")))>=8 and norm(m["title"]) in gist}
A={m["material_id"] for m in stamp if len(norm(m.get("title")))>=8 and norm(m["title"]) not in gist}
short=len(stamp)-len(P)-len(A)
p16=sum(1 for m in stamp if norm(m.get("passage"))[:16] and norm(m["passage"])[:16] in gist)
p40=sum(1 for m in stamp if norm(m.get("passage"))[:40] and norm(m["passage"])[:40] in gist)
print("stamp",len(stamp),"present",len(P),"absent",len(A),"short",short,"passage16",p16,"passage40",p40)
def strat(g,name):
    gp=[m for m in g if m["material_id"] in P]; ga=[m for m in g if m["material_id"] in A]
    r1=sum(1 for m in gp if reached(m["material_id"])); r2=sum(1 for m in ga if reached(m["material_id"]))
    z,p=zt(r1,len(gp),r2,len(ga))
    print(name,f"present {r1}/{len(gp)}={r1/len(gp):.4f} absent {r2}/{len(ga)}={r2/len(ga):.4f} z={z} p={p}")
strat(stamp,"overall")
for e in ("pre","reg","act"):
    strat([m for m in stamp if era(m)==e],f"era={e}")
for e in ("pre","reg","act"):
    strat([m for m in stamp if era(m)==e and m["material_id"] in pkt],f"era={e}&packet")
pre_abs=[m for m in stamp if era(m)=="pre" and m["material_id"] not in pkt]
strat(pre_abs,"pre-reg&packet-absent")
comp_p=sum(1 for m in stamp if m["material_id"] in P and era(m)=="pre")
comp_a=sum(1 for m in stamp if m["material_id"] in A and era(m)=="pre")
print("composition pre: present",round(comp_p/len(P),3),"absent",round(comp_a/len(A),3))

import json, glob, re
CAP="20261127"
def d8(i):
    m=re.search(r"-(\d{8})-", i or ""); return m.group(1) if m else "00000000"
hyp_pat=re.compile(r"HYP-\d{8}-[0-9a-f]+")
mats=[]
for f in sorted(glob.glob("state/materials.d/*.jsonl"))+ (["state/materials.jsonl"] if glob.glob("state/materials.jsonl") else []):
    for line in open(f,encoding="utf-8"):
        line=line.strip()
        if line:
            try: mats.append(json.loads(line))
            except Exception: pass
new=[m for m in mats if d8(m["material_id"])>="20261126"]
for kind in ("research_excerpt","literary_text"):
    sub=[m for m in new if m.get("kind")==kind]
    cue=sum(1 for m in sub if hyp_pat.findall(m.get("source_note") or ""))
    pair=sum(1 for m in sub if len(set(hyp_pat.findall(m.get("source_note") or "")))>=2)
    print(f"M4 {kind} n={len(sub)} cue={cue} pair={pair}")
    for b in sorted({d8(m["material_id"]) for m in sub}):
        g=[m for m in sub if d8(m["material_id"])==b]
        c=sum(1 for m in g if hyp_pat.findall(m.get("source_note") or ""))
        pr=sum(1 for m in g if len(set(hyp_pat.findall(m.get("source_note") or "")))>=2)
        print(f"M4   {kind} {b}: n={len(g)} cue={c} pair={pr}")
